import {showCellCutaway} from './cell-3d.js?v=20261023-physicscomplete01';
import {partsFor,cellParts,selectedPart} from './cell-anatomy.js?v=20261023-physicscomplete01';
import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {cellFigure,microscopeFigure,organelleNames} from './biology-figures.js?v=20261023-physicscomplete01';
import {biologyTasks,microscopeInFocus} from './biology-models.js?v=20261023-physicscomplete01';
import {catalogTaskCorrect,escapeLab} from './catalog-labs.js?v=20261023-physicscomplete01';
export function showBiology(kind,t=null,w={},checked=false){const [base,type,highlight]=kind.split(':');kind=base;t??=biologyTasks[kind]?.[0];if(type)t={...t,type,highlight};if(!t)return;const micro=kind==='microscopy';if(!micro){showCellCutaway({type:t.type,highlight:selectedPart(t.type,w.inspect||t.highlight),title:t.title});return;}const art=microscopeFigure(w);renderDiagram(t.title,micro?'Light microscopy · simulation':w.inspect?organelleNames[w.inspect]:organelleNames[t.highlight]||'Compare supplied evidence',art+(t.data?'<p class="bio-evidence">'+escapeLab(t.data)+'</p>':'')+'<p class="diagram-caption">'+(micro?'Schematic tissue. View enlargement is not calibrated magnification.':'Symbolic cutaway with exaggerated structures. Specimens are enlarged separately; drawings do not share a scale.')+'</p>',checked?'REASONING CHECKED':'OBSERVE · PREDICT · EXPLAIN');}
export function mountBiology(l,p,root,{save,done,feedback}){
 const kind=l.widget.slice(4),tasks=biologyTasks[kind],w=p.widget;w.task??=0;w.answers??={};w.passed??=[];w.focus??=0;w.zoom??=1;
 const t=tasks[w.task%tasks.length],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);
 const focusTask=kind==='microscopy'&&t.id==='prepare';
 root.innerHTML='<p><b>'+(w.task+1)+' / '+tasks.length+' · '+escapeLab(t.title)+'</b></p><p>'+escapeLab(t.prompt)+'</p>'+(focusTask?'<label class="field-label" for="bioFocus">Focus · find the clearest cell walls</label><input id="bioFocus" type="range" min="0" max="8" step="1" value="'+w.focus+'"><label class="field-label" for="bioZoom">View enlargement · does not add resolving power</label><input id="bioZoom" type="range" min="1" max="3" step=".5" value="'+w.zoom+'">':'')+t.fields.map(f=>'<label class="field-label" for="bio-'+f.key+'">'+escapeLab(f.label)+'</label>'+(f.type==='number'?'<input class="lab-input" id="bio-'+f.key+'" type="number" step="any">':'<select class="lab-select" id="bio-'+f.key+'"><option value="">Choose…</option>'+f.options.map(o=>'<option value="'+escapeLab(o.value)+'">'+escapeLab(o.label)+'</option>').join('')+'</select>')).join('')+'<button class="secondary" id="checkBio">Check reasoning</button><button class="secondary" id="nextBio">Next investigation →</button><p id="bioProgress">'+w.passed.length+' / '+tasks.length+' correct</p>';
 if(kind!=='microscopy'){const panel=document.createElement('details');panel.className='cell-inspector';panel.open=true;const selected=selectedPart(t.type,w.inspect||t.highlight);panel.innerHTML='<summary>Explore the cell</summary><label class=field-label for=cellStructure>Select a structure</label><select class=lab-select id=cellStructure>'+partsFor(t.type).map(p=>'<option value="'+p.id+'"'+(p.id===selected?' selected':'')+'>'+p.name+'</option>').join('')+'</select><p id=cellFunction></p>';root.prepend(panel);if(!selected)w.inspect=partsFor(t.type)[0].id;$('#cellFunction').textContent=cellParts[selected||w.inspect].description;$('#cellStructure').onchange=e=>{w.inspect=e.target.value;$('#cellFunction').textContent=cellParts[w.inspect].description;save();draw();};}
 const correct=()=>catalogTaskCorrect(t,a)&&(!focusTask||microscopeInFocus(w.focus));const draw=()=>showBiology(kind,t,w,w.passed.includes(t.id)&&correct());
 for(const f of t.fields){const el=$('#bio-'+f.key);el.value=a[f.key]??'';el[el.tagName==='SELECT'?'onchange':'oninput']=e=>{a[f.key]=e.target.value;save();draw();};}
 if(focusTask){$('#bioFocus').oninput=e=>{w.focus=Number(e.target.value);save();draw();};$('#bioZoom').oninput=e=>{w.zoom=Number(e.target.value);save();draw();};}
 draw();$('#checkBio').onclick=()=>{if(!correct()){feedback(focusTask&&!microscopeInFocus(w.focus)?'Adjust focus until the simulated cell walls are clearest, then check your lens and control choices.':t.feedback,true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#bioProgress').textContent=w.passed.length+' / '+tasks.length+' correct';feedback(t.success);if(w.passed.length===tasks.length){p.widgetDone=true;save();done();}};
 $('#nextBio').onclick=()=>{w.task=(w.task+1)%tasks.length;delete w.inspect;save();feedback('');mountBiology(l,p,root,{save,done,feedback});};
}
